insert into public.content_blocks (key, section, title, subtitle, body, claim_status, review_note, published, sort_order) values
  ('about.intro', 'about', 'Solar PV systems for homes and businesses', null, 'JFL Solar provides solar PV installation, consultancy and equipment distribution in the Philippines. We work with homeowners who want lower electricity bills and backup power, with commercial and industrial clients planning larger systems, and with DIY buyers and professional installers who need dependable equipment.
