  ('00000000-0000-4000-8000-000000000101', null, 'published', true, 'quote', null, null, false, null, 'goodwe-gw6000-es-c10-hybrid-inverter', 'GoodWe GW6000-ES-C10 hybrid inverter', 'GoodWe', 'GW6000-ES-C10', '00000000-0000-4000-8000-0000000000c2', '6 kW single-phase hybrid inverter for systems with battery storage.', 'Hybrid inverter featured in the reference package materials. Ask us for the full datasheet, compatible batteries and current pricing.', '[{"label":"Inverter type","value":"Hybrid"},{"label":"Rated output","value":"6 kW"},{"label":"Model","value":"GW6000-ES-C10"}]'::jsonb, 'on_request', 'Model and rating from the October 2026 Trio Package flyer. Confirm full specifications before production.', true, 10),
  ('00000000-0000-4000-8000-000000000102', null, 'published', true, 'quote', null, null, false, null, 'jinko-solar-620w-bifacial-panel', 'Jinko Solar 620 W bifacial panel', 'Jinko Solar', '66HL4M-BDV', '00000000-0000-4000-8000-0000000000c1', '620 W bifacial PV module.', 'Bifacial module featured in the reference package materials. Ask us for the datasheet and current pricing.', '[{"label":"Rated power","value":"620 W"},{"label":"Module type","value":"Bifacial"},{"label":"Model","value":"66HL4M-BDV"}]'::jsonb, 'on_request', 'Rating and model as printed on the Trio Package flyer. Confirm the full model code and datasheet.', true, 10),
  ('00000000-0000-4000-8000-000000000103', null, 'published', true, 'quote', null, null, false, null, 'alltopelec-16-5kwh-battery', 'AllTopElec 16.5 kWh battery', 'AllTopElec', null, '00000000-0000-4000-8000-0000000000c3', '324 Ah / 16.5 kWh battery for hybrid systems.', 'Battery featured in the reference package materials. Ask us for the model code, datasheet and compatible inverters.', '[{"label":"Capacity","value":"324 Ah"},{"label":"Energy","value":"16.5 kWh"}]'::jsonb, 'on_request', 'Capacity from the Trio Package flyer. Model code not shown on the flyer — confirm.', true, 10),
  ('00000000-0000-4000-8000-000000000104', null, 'published', true, 'quote', null, null, false, null, 'dyness-battery-storage', 'Dyness battery storage', 'Dyness', null, '00000000-0000-4000-8000-0000000000c3', 'Battery storage options from Dyness. Models to be confirmed.', 'Ask us which Dyness models are currently offered and which inverters they pair with.', '[]'::jsonb, 'on_request', 'Sample entry based on the brands listed in the supplier flyer. Listing a brand does not imply authorised-distributor status. Confirm models, specifications and availability.', false, 20),
