  ('00000000-0000-4000-8000-000000000108', null, 'published', true, 'quote', null, null, false, null, 'pv-cable-and-mc4-connectors', 'PV cable and MC4 connectors', null, null, '00000000-0000-4000-8000-0000000000c5', 'DC solar cable and MC4-type connectors. Sizes to be confirmed.', 'Tell us your string layout and cable runs and we will quote suitable cable sizes and connectors.', '[]'::jsonb, 'on_request', 'Generic catalogue line from the supplier flyer. Add sizes, brands and specifications.', false, 10),
  ('00000000-0000-4000-8000-000000000109', null, 'published', true, 'quote', null, null, false, null, 'battery-cables-and-terminal-lugs', 'Battery cables and terminal lugs', null, null, '00000000-0000-4000-8000-0000000000c5', 'Battery interconnect cables and terminal lugs. Sizes to be confirmed.', 'Ask us for battery cable sizes and lugs matched to your inverter and battery.', '[]'::jsonb, 'on_request', 'Generic catalogue line from the supplier flyer.', false, 20),
  ('00000000-0000-4000-8000-00000000010a', null, 'published', true, 'quote', null, null, false, null, 'ac-dc-protection-and-rapid-shutdown', 'AC and DC protection devices and rapid shutdown', null, null, '00000000-0000-4000-8000-0000000000c6', 'Breakers, surge protection and rapid shutdown devices (RSD). Ratings to be confirmed.', 'Protection devices are selected per system. Share your system size and we will recommend suitable ratings.', '[]'::jsonb, 'on_request', 'Generic catalogue line from the supplier flyer.', false, 10),
