insert into public.packages (id, sku, status, is_sample, slug, name, summary, description, package_type, system_type, inverter_kw, array_kwp, battery_kwh, components, inclusions, exclusions, pricing_mode, price_php, price_basis, price_is_sample, installation_terms, fulfillment, fulfillment_notes, promo_label, promo_start, promo_end, hide_when_expired, warranty_terms, admin_notes, featured, sort_order) values
  ('00000000-0000-4000-8000-000000000201', null, 'published', true, 'trio-6kw-hybrid-equipment-bundle', 'Trio Package — 6 kW hybrid equipment bundle', 'Hybrid inverter, ten 620 W bifacial panels and a 16.5 kWh battery. Equipment only, for pickup.', 'A matched set of the three core components for a hybrid solar system. Accessories, mounting, protection devices and installation are not included — ideal for installers and experienced DIY buyers who are sourcing the balance of system themselves.', 'equipment_bundle', 'hybrid', 6, 6.2, 16.5, '[{"label":"Hybrid inverter","detail":"GoodWe GW6000-ES-C10, 6 kW","quantity":"1 unit"},{"label":"Solar panels","detail":"Jinko Solar 620 W bifacial (66HL4M-BDV), 6.2 kWp total","quantity":"10 pcs"},{"label":"Battery","detail":"AllTopElec 324 Ah / 16.5 kWh","quantity":"1 unit"}]'::jsonb, array['Hybrid inverter', '10 × 620 W bifacial solar panels', '16.5 kWh battery']::text[], array['Accessories (mounting, cables, protection devices)', 'Installation and commissioning', 'Delivery']::text[], 'fixed', 205000, 'Pickup price, equipment only', true, 'Not included. Installation can be quoted separately.', 'pickup', 'Pickup at our Dasmariñas, Cavite warehouse. Delivery charges, if needed, are confirmed during quotation.', 'October 2026 promotion', '2026-10-01', '2026-10-31', false, null, 'From the October 2026 reference flyer. ₱205,000 and the promotion dates are reference material, NOT an approved current offer. Confirm or replace before production.', true, 10),
  ('00000000-0000-4000-8000-000000000202', null, 'published', true, 'residential-hybrid-system-6kw-installed', 'Residential hybrid system — 6 kW, installed', 'Solar with battery backup for homes, supplied and installed by JFL Solar.', 'A hybrid system lets your home use solar power during the day, store energy in a battery and keep essential loads running during outages. Final design, components and price are confirmed after a site assessment.', 'installed_system', 'hybrid', 6, 6.2, 16.5, '[{"label":"Hybrid inverter","detail":"6 kW","quantity":null},{"label":"Solar panels","detail":"Approx. 6.2 kWp array","quantity":null},{"label":"Battery","detail":"16.5 kWh","quantity":null}]'::jsonb, array['Site assessment', 'System design and written proposal', 'Supply of inverter, panels and battery', 'Mounting, cabling and protection devices', 'Installation and commissioning']::text[], array['Structural roof repairs', 'Utility or permit fees, where applicable', 'Anything not stated in the final quotation']::text[], 'quote', null, null, false, 'Installation schedule, site assessment and feasibility are confirmed during quotation.', 'installed', null, null, null, null, false, null, 'Sample package for the proposal. Confirm sizes, inclusions and pricing before production.', true, 20),
  ('00000000-0000-4000-8000-000000000203', null, 'published', true, 'residential-on-grid-system-5kw-installed', 'Residential on-grid system — 5 kW, installed', 'Daytime solar for homes focused on lowering electricity bills. No battery.', 'An on-grid system powers your home with solar during the day and draws from the grid when needed. It does not provide backup power during outages. Final design and price are confirmed after a site assessment.', 'installed_system', 'on_grid', 5, 5.58, null, '[{"label":"On-grid inverter","detail":"5 kW","quantity":null},{"label":"Solar panels","detail":"Approx. 5.6 kWp array","quantity":null}]'::jsonb, array['Site assessment', 'System design and written proposal', 'Supply of inverter and panels', 'Mounting, cabling and protection devices', 'Installation and commissioning']::text[], array['Battery storage', 'Structural roof repairs', 'Utility or permit fees, where applicable']::text[], 'quote', null, null, false, 'Installation schedule, site assessment and feasibility are confirmed during quotation.', 'installed', null, null, null, null, false, null, 'Sample package for the proposal.', true, 30),
  ('00000000-0000-4000-8000-000000000204', null, 'published', true, 'commercial-on-grid-system', 'Commercial and industrial on-grid system', 'Rooftop solar for offices, shops, factories and warehouses, sized to your load.', 'For commercial and industrial sites we start with your load profile and electricity bills, assess the roof or ground area, and prepare an engineered proposal. System capacity is set after assessment.', 'installed_system', 'on_grid', null, null, null, '[]'::jsonb, array['Load and bill review', 'Site assessment', 'Engineered proposal', 'Supply, installation and commissioning']::text[], array['Anything not stated in the final quotation']::text[], 'quote', null, null, false, 'Scope, schedule and feasibility are confirmed after the site assessment.', 'installed', null, null, null, null, false, null, 'Sample package for the proposal.', false, 40),
  ('00000000-0000-4000-8000-000000000205', null, 'published', true, 'off-grid-starter-equipment-bundle', 'Off-grid starter equipment bundle', 'Demonstrates an ended promotion: the promotional price is withdrawn automatically.', 'Sample bundle used to show how the website handles a promotion after its end date. The promotional price is no longer displayed and visitors are invited to request current pricing.', 'equipment_bundle', 'off_grid', 3, 2.48, 5, '[{"label":"Off-grid inverter","detail":"3 kW","quantity":"1 unit"},{"label":"Solar panels","detail":"620 W, 2.48 kWp total","quantity":"4 pcs"},{"label":"Battery","detail":"5 kWh","quantity":"1 unit"}]'::jsonb, array['Off-grid inverter', '4 solar panels', 'Battery']::text[], array['Accessories', 'Installation', 'Delivery']::text[], 'fixed', 99000, 'Pickup price, equipment only', true, 'Not included.', 'pickup_or_delivery', 'Delivery charges are confirmed during quotation.', 'September 2026 promotion', '2026-09-01', '2026-09-30', false, null, 'Invented sample to demonstrate promotion expiry. Delete or replace before production.', false, 50)
insert into public.projects (id, status, is_sample, slug, title, location, project_type, system_size_kwp, system_size_confirmed, scope, summary, description, admin_notes, featured, sort_order) values
  ('00000000-0000-4000-8000-000000000301', 'published', true, 'sample-residential-hybrid-rooftop', 'Sample project — residential hybrid rooftop', 'Cavite (sample)', 'residential', null, false, 'Site assessment, system design, supply, installation and commissioning', 'Placeholder entry showing how a home installation will be presented.', 'This is a sample entry used to demonstrate the project gallery during the proposal stage. It does not describe a completed JFL Solar installation. Staff can replace the text and photos in the admin dashboard once a project is approved for publication.', 'Sample project for the proposal. Not a completed JFL Solar installation. Replace text and photos with an approved project, then untick ''Sample''.', true, 10),
  ('00000000-0000-4000-8000-000000000302', 'published', true, 'sample-commercial-rooftop', 'Sample project — commercial rooftop', 'Calabarzon (sample)', 'commercial', null, false, 'Consultancy, engineered proposal, installation', 'Placeholder entry showing how a commercial project will be presented.', 'This is a sample entry used to demonstrate the project gallery during the proposal stage. It does not describe a completed JFL Solar installation.', 'Sample project for the proposal. Not a completed JFL Solar installation. Replace text and photos with an approved project, then untick ''Sample''.', true, 20),
  ('00000000-0000-4000-8000-000000000303', 'published', true, 'sample-industrial-warehouse', 'Sample project — industrial warehouse roof', 'Luzon (sample)', 'industrial', null, false, 'Equipment supply for a contractor-led installation', 'Placeholder entry showing how an equipment-supply project will be presented.', 'This is a sample entry used to demonstrate the project gallery during the proposal stage. It does not describe a completed JFL Solar installation.', 'Sample project for the proposal. Not a completed JFL Solar installation. Replace text and photos with an approved project, then untick ''Sample''.', true, 30)
